                        Text(String(format: "%.1f%%", state.confidence * 100))
                            .font(.system(size: 12, weight: .bold, design: .monospaced))
                            .foregroundStyle(Theme.cyan)
                    }
                    ConfidenceBar(value: state.confidence)
