    // 与 controlEngine 区别：
    //   controlEngine = AI 注入的按键（输出）
    //   keyboardMonitor = 用户物理按下的键（输入，仅显示用 + 录制专家演示）
    let keyboardMonitor = KeyboardMonitor()

