/// 全局主题：FSD 驾驶舱配色与发光参数
enum Theme {
    // 背景
    static let bgPure      = Color.black                       // #000000
    static let bgCard      = Color.white.opacity(0.045)        // 卡片底
    static let bgCardEdge  = Color.white.opacity(0.08)         // 卡片描边

    // 主色 / 强调
