                .buttonStyle(.plain)
                .disabled(state.bpfInstalling || password.isEmpty)
            }
        }
        .padding(28)
        .background {
            RoundedRectangle(cornerRadius: 24)
                .fill(.ultraThinMaterial)
                .overlay {
                    RoundedRectangle(cornerRadius: 24)
                        .stroke(Theme.cyan.opacity(0.3), lineWidth: 1)
                }
        }
        .frame(width: 340)
    }
}


