import SwiftUI
import AppKit
import Darwin   // mach_task_basic_info：诊断进程内存占用（验证"积压→内存涨"根因）
import CoreVideo  // CVPixelBuffer：YOLO 直通帧跳帧缓冲
import MetalKit   // MTKView：MetalGoose 插帧渲染承载
