/// 圆角卡片容器：半透明底 + 细描边 + 内高光
struct GlowCard<Content: View>: View {
    var padding: CGFloat = 16
    @ViewBuilder var content: Content

    var body: some View {
        content
            .padding(padding)
            .background(
                ZStack {
                    RoundedRectangle(cornerRadius: 16, style: .continuous)
                        .fill(Theme.bgCard)
                    RoundedRectangle(cornerRadius: 16, style: .continuous)
