    func runNetworkLocateStep() {
        // 懒初始化NetworkHealer（自愈引擎：网络+视觉双模+后台诊断修复）
        if healer == nil {
            os_unfair_lock_lock(&healerInitLock)
            defer { os_unfair_lock_unlock(&healerInitLock) }
            if healer == nil {
