        didSet {
            if gameModeBoost != oldValue {
                applyMainThreadBoost(gameModeBoost)
                // 启用时加强心跳，防止系统冻结
                if gameModeBoost {
                    startAntiFreeze()
                } else {
                    stopAntiFreeze()
                }
            }
        }
    }

