    // tick() 每帧调用 update()，结果同步到 self.mode
    // 阈值由本类的 degradeThreshold 等属性同步过去，UI 可调
    let degradeStm = DegradeStateMachine()

    // ── 行驶录制引擎（画面+控制量 → recordings/）──
    // isRecording didSet 触发启停，tick() 每帧调用 appendFrame
