        return Text(txt)
            .font(.system(size: 9, weight: .semibold, design: .monospaced))
            .foregroundStyle(col)
            .lineLimit(1)
            .padding(.horizontal, 8).padding(.vertical, 3)
            .background(Capsule().fill(col.opacity(0.12)))
            .overlay(Capsule().strokeBorder(col.opacity(0.35), lineWidth: 1))
