/// - `.ruleFallback` 规则：规则兜底 + 脱困，紧急保命用，不当主驾。
enum DriveModeGroup: String, CaseIterable, Identifiable {
    case e2eDrive     = "端到端主驾"
    case ruleFallback = "规则"

