    func startDriving() {
        // 权限检查：按键注入需要辅助功能权限
        // 无权限时引导用户到系统设置，不启动
        guard controlEngine.checkPermission() else {
            controlPermissionDenied = true
            controlEngine.openAccessibilitySettings()
