    // MARK: - 防冻结心跳（对抗Game Mode冻结）

    /// 启动防冻结心跳：每100ms强制唤醒主线程+发送空事件
    /// 原理：系统判定"最近有用户输入事件"的进程为活跃进程，不冻结
    private func startAntiFreeze() {
        stopAntiFreeze()  // 先停止旧的

        let queue = DispatchQueue(label: "com.aurora.antifreeze", qos: .userInteractive)
        let timer = DispatchSource.makeTimerSource(queue: queue)
        timer.schedule(deadline: .now(), repeating: 0.1, leeway: .milliseconds(5))

        timer.setEventHandler { [weak self] in
            // 1. 主线程心跳（强制唤醒）
            DispatchQueue.main.async {
                // 空操作即可，只需唤醒主线程RunLoop
                _ = Date()
            }

            // 2. 发送空鼠标移动事件（欺骗系统认为有用户活动）
            // 注意：移动量为0，不会真的移动鼠标
            if let event = CGEvent(mouseEventSource: nil,
                                   mouseType: .mouseMoved,
                                   mouseCursorPosition: .zero,
                                   mouseButton: .left) {
                event.post(tap: .cghidEventTap)
            }
        }

        timer.resume()
        antiFreezeTimer = timer
        dlog("[antifreeze] 心跳已启动（100ms间隔）")
    }

    /// 停止防冻结心跳
    private func stopAntiFreeze() {
        antiFreezeTimer?.cancel()
        antiFreezeTimer = nil
    }

