            DispatchQueue.main.async { [weak self] in
                self?.networkLocateScore = 0
                self?.networkLocateMode = "not_ready"
            }
            return
        }

        // 从自愈引擎获取当前最佳定位
        if let (px, py, hdg, mode) = h.currentLocation() {
            if let last = lastNetworkLocPos {
                let dx = px - last.x, dy = py - last.y
                if dx * dx + dy * dy > 16 {
