    // escapeController: .recover 态脱困策略（倒车→转向→前进）
    // ruleController:   .yolo/.rule 态 YOLO 检测→控制量规则
    // confidenceEst:    E2E 无置信度头，用启发式从输出/画面估算
    let escapeController = EscapeController()
    let ruleController = RuleController()
