    func stopDriving() {
        isDriving = false
        controlEngine.releaseAll()
        keyboardMonitor.stop()
        captureEngine.stop()
        // networkLocator.stop()   // 旧网络抓包定位已移除
        degradeStm.reset()
        escapeController.reset()
        lastDecided = .e2e
        confidenceEst.reset()
        inferenceEngine.reset()
        assistEngine.reset()
        yoloEngine.reset()
        speedOCR.reset()
        currentCommand = .idle
        if isRecording { isRecording = false }   // didSet 会触发 recordEngine.stop()
    }

