                    .padding(.vertical, 8)
                    .background(Theme.cyan.opacity(0.2), in: Capsule())
                    .foregroundStyle(Theme.cyan)
                }
                .buttonStyle(.plain)
                .disabled(state.daemonInstalling || password.isEmpty)
            }
        }
        .padding(28)
        .background {
            RoundedRectangle(cornerRadius: 24)
                .fill(.ultraThinMaterial)
