struct DaemonSetupManager {

    /// LaunchDaemon 标识
    static let daemonLabel = "com.aurora.drive.daemon"
    static let daemonPlistPath = "/Library/LaunchDaemons/\(daemonLabel).plist"
    static let daemonExecutablePath = "/usr/local/bin/aurora-drive-daemon"

    /// 检查是否已安装为 LaunchDaemon
    static func isDaemonInstalled() -> Bool {
        return FileManager.default.fileExists(atPath: daemonPlistPath)
    }

    /// 检查当前是否以 LaunchDaemon 模式运行（通过环境变量判断）
    static func isRunningAsDaemon() -> Bool {
        return ProcessInfo.processInfo.environment["AURORA_DAEMON_MODE"] == "1"
    }

    /// 需要安装吗？（未安装 且 当前不是 daemon 模式）
    static func needsInstall() -> Bool {
        return !isDaemonInstalled() && !isRunningAsDaemon()
    }

    /// 安装为 LaunchDaemon
    /// - Parameter password: 用户在 App 内输入的密码
    /// - Parameter currentExecutablePath: 当前可执行文件路径（用于复制到系统目录）
    /// - Returns: 是否安装成功
    static func install(password: String, currentExecutablePath: String) -> (success: Bool, message: String) {
        // 1. 生成安装脚本
        let scriptContent = """
        #!/bin/bash
        set -e

        # 1. 复制可执行文件到系统目录
        cp "\(currentExecutablePath)" \(daemonExecutablePath)
        chmod 755 \(daemonExecutablePath)
        chown root:wheel \(daemonExecutablePath)

        # 2. 创建 LaunchDaemon plist
        cat > \(daemonPlistPath) << 'PLIST_EOF'
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
            <key>Label</key>
            <string>\(daemonLabel)</string>
            <key>ProgramArguments</key>
            <array>
                <string>\(daemonExecutablePath)</string>
                <string>--daemon</string>
            </array>
            <key>EnvironmentVariables</key>
            <dict>
                <key>AURORA_DAEMON_MODE</key>
                <string>1</string>
            </dict>
            <key>RunAtLoad</key>
            <true/>
            <key>KeepAlive</key>
            <true/>
            <key>ProcessType</key>
            <string>Interactive</string>
            <key>Nice</key>
            <integer>-20</integer>
            <key>StandardOutPath</key>
