    /// - Returns: 是否安装成功
    static func install(password: String, currentExecutablePath: String) -> (success: Bool, message: String) {
        // 1. 生成安装脚本
        let scriptContent = """
        #!/bin/bash
        set -e

        # 1. 复制可执行文件到系统目录
        cp "\(currentExecutablePath)" \(daemonExecutablePath)
        chmod 755 \(daemonExecutablePath)
        chown root:wheel \(daemonExecutablePath)

        # 2. 创建 LaunchDaemon plist
        cat > \(daemonPlistPath) << 'PLIST_EOF'
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
            <key>Label</key>
            <string>\(daemonLabel)</string>
            <key>ProgramArguments</key>
            <array>
                <string>\(daemonExecutablePath)</string>
                <string>--daemon</string>
            </array>
            <key>EnvironmentVariables</key>
            <dict>
                <key>AURORA_DAEMON_MODE</key>
                <string>1</string>
            </dict>
            <key>RunAtLoad</key>
            <true/>
            <key>KeepAlive</key>
            <true/>
            <key>ProcessType</key>
            <string>Interactive</string>
            <key>Nice</key>
            <integer>-20</integer>
            <key>StandardOutPath</key>
            <string>/tmp/aurora_daemon.log</string>
            <key>StandardErrorPath</key>
            <string>/tmp/aurora_daemon_error.log</string>
        </dict>
        </plist>
        PLIST_EOF

        # 3. 设置权限并加载
        chown root:wheel \(daemonPlistPath)
        chmod 644 \(daemonPlistPath)
        launchctl load \(daemonPlistPath)
        launchctl start \(daemonLabel)

        echo "DAEMON_SETUP_DONE"
        """

        let scriptPath = "/tmp/aurora_daemon_setup.sh"
        do {
            try scriptContent.write(toFile: scriptPath, atomically: true, encoding: .utf8)
            try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: scriptPath)
        } catch {
            return (false, "写脚本失败: \(error.localizedDescription)")
        }

        // 2. 用 osascript 以管理员权限运行
        // 注意：macOS 26+ 上 osascript 的 "with administrator privileges" 不稳定
        // 改用 sudo -S 从 stdin 读取密码，更可靠
        let escapedPwd = password.replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")

        // 方案A：先尝试 osascript（如果系统支持）
        let appleScript = "do shell script \"bash \(scriptPath)\" password \"\(escapedPwd)\" with administrator privileges"

        let task = Process()
        task.launchPath = "/usr/bin/osascript"
        task.arguments = ["-e", appleScript]

