            }

            Spacer()

            // 右: Daemon状态药丸 + BPF状态药丸 + 模式标识 + 运行灯
            HStack(spacing: 10) {
                // Daemon系统服务状态药丸（最高优先级标识）
                if state.isDaemonMode {
                    HStack(spacing: 4) {
                        Image(systemName: "shield.lefthalf.filled.badge.checkmark")
