            col = Theme.danger; txt = "插帧异常 · \(err)"
        } else if !state.upscaleEnabled {
            col = Theme.textTertiary; txt = "插帧 · 关"
        } else if let live = state.upscaleLive {
            col = Theme.cyan; txt = "插帧中 · \(live)"
        } else {
            col = Theme.cyan; txt = "插帧中 · 等待"
