    let title: String
    var body: some View {
        HStack(spacing: 8) {
            RoundedRectangle(cornerRadius: 1.5)
                .fill(Theme.cyan)
                .frame(width: 3, height: 12)
                .shadow(color: Theme.cyan, radius: 4)
            Text(title)
                .font(.system(size: 11, weight: .bold, design: .rounded))
                .tracking(2.5)
                .foregroundStyle(Theme.textSecondary)
            Spacer()
        }
    }
}


