    var confidence: Double = 0.92       // 0~1

    /// 上一帧状态机决策档位：用于检测"刚切入 .recover"的边沿，
    /// 让脱困只 enter 一次（避免每帧 phase==.done 就 re-enter 抵消超时）。
    private var lastDecided: DriveMode = .e2e

    /// 有效车速（km/h）：每帧由 OCR 新鲜读数（EMA 平滑）或一阶滤波回退计算
