    /// 手动框选：拖拽起点/当前点（视口坐标）
    @State private var dragStart: CGPoint? = nil
    @State private var dragCurrent: CGPoint? = nil

    var body: some View {
        GeometryReader { geo in
            ZStack {
                Color.black

            // ── 真实游戏画面（CGDisplayStream 画面流）──
            // 当截屏引擎运行时，显示实时游戏画面
            // 未运行时，显示纯黑占位 + 提示文字
            if state.isStreaming {
