            defer { os_unfair_lock_unlock(&healerInitLock) }
            if coordinateCapture == nil {
                let cc = CoordinateCapture()
                let ok = cc.start()
                pcapLog("[NETWORK-LOCATE] cc.start()返回=\(ok)")
