        }

        // 从 CoordinateCapture 获取定位
        if let pose = cc.read(maxAge: 1.0) {
            let (px, py, hdg) = worldToMapPixel(pose)
            if let last = lastNetworkLocPos {
                let dx = px - last.x, dy = py - last.y
                if dx * dx + dy * dy > 16 {
