import Foundation

/// Daemon 自动安装器：首次启动检测是否为 LaunchDaemon，如不是则引导用户安装
/// 用户只需输入一次密码，之后系统以最高优先级运行，永久无需再输
struct DaemonSetupManager {

    /// LaunchDaemon 标识
    static let daemonLabel = "com.aurora.drive.daemon"
    static let daemonPlistPath = "/Library/LaunchDaemons/\(daemonLabel).plist"
    static let daemonExecutablePath = "/usr/local/bin/aurora-drive-daemon"

    /// 检查是否已安装为 LaunchDaemon
    static func isDaemonInstalled() -> Bool {
        return FileManager.default.fileExists(atPath: daemonPlistPath)
    }

    /// 检查当前是否以 LaunchDaemon 模式运行（通过环境变量判断）
    static func isRunningAsDaemon() -> Bool {
        return ProcessInfo.processInfo.environment["AURORA_DAEMON_MODE"] == "1"
    }

    /// 需要安装吗？（未安装 且 当前不是 daemon 模式）
    static func needsInstall() -> Bool {
        return !isDaemonInstalled() && !isRunningAsDaemon()
    }

    /// 安装为 LaunchDaemon
    /// - Parameter password: 用户在 App 内输入的密码
    /// - Parameter currentExecutablePath: 当前可执行文件路径（用于复制到系统目录）
    /// - Returns: 是否安装成功
    static func install(password: String, currentExecutablePath: String) -> (success: Bool, message: String) {
        // 1. 生成安装脚本
        let scriptContent = """
        #!/bin/bash
        set -e

        # 1. 复制可执行文件到系统目录
        cp "\(currentExecutablePath)" \(daemonExecutablePath)
        chmod 755 \(daemonExecutablePath)
        chown root:wheel \(daemonExecutablePath)

        # 2. 创建 LaunchDaemon plist
        cat > \(daemonPlistPath) << 'PLIST_EOF'
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
            <key>Label</key>
            <string>\(daemonLabel)</string>
            <key>ProgramArguments</key>
            <array>
                <string>\(daemonExecutablePath)</string>
                <string>--daemon</string>
            </array>
            <key>EnvironmentVariables</key>
            <dict>
                <key>AURORA_DAEMON_MODE</key>
                <string>1</string>
            </dict>
            <key>RunAtLoad</key>
            <true/>
            <key>KeepAlive</key>
            <true/>
            <key>ProcessType</key>
            <string>Interactive</string>
            <key>Nice</key>
            <integer>-20</integer>
            <key>StandardOutPath</key>
            <string>/tmp/aurora_daemon.log</string>
            <key>StandardErrorPath</key>
            <string>/tmp/aurora_daemon_error.log</string>
        </dict>
        </plist>
        PLIST_EOF

        # 3. 设置权限并加载
        chown root:wheel \(daemonPlistPath)
        chmod 644 \(daemonPlistPath)
        launchctl load \(daemonPlistPath)
        launchctl start \(daemonLabel)

        echo "DAEMON_SETUP_DONE"
        """

        let scriptPath = "/tmp/aurora_daemon_setup.sh"
        do {
            try scriptContent.write(toFile: scriptPath, atomically: true, encoding: .utf8)
            try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: scriptPath)
        } catch {
            return (false, "写脚本失败: \(error.localizedDescription)")
        }

        // 2. 用 osascript 以管理员权限运行
        // 注意：macOS 26+ 上 osascript 的 "with administrator privileges" 不稳定
        // 改用 sudo -S 从 stdin 读取密码，更可靠
        let escapedPwd = password.replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")

        // 方案A：先尝试 osascript（如果系统支持）
        let appleScript = "do shell script \"bash \(scriptPath)\" password \"\(escapedPwd)\" with administrator privileges"

        let task = Process()
        task.launchPath = "/usr/bin/osascript"
        task.arguments = ["-e", appleScript]

        let pipe = Pipe()
        task.standardOutput = pipe
        task.standardError = pipe

        do {
            try task.run()
            task.waitUntilExit()

            if task.terminationStatus == 0 {
                // 验证是否安装成功
                if isDaemonInstalled() {
                    return (true, "已成功安装为系统服务，重启后将以最高优先级运行")
                }
            }

            // osascript 失败，尝试方案B：sudo -S 从 stdin 读取密码
            let sudoTask = Process()
            sudoTask.launchPath = "/bin/bash"
            sudoTask.arguments = ["-c", "echo \"\(escapedPwd)\" | sudo -S bash \(scriptPath) 2>&1"]

            let sudoPipe = Pipe()
            sudoTask.standardOutput = sudoPipe
            sudoTask.standardError = sudoPipe

            try sudoTask.run()
            sudoTask.waitUntilExit()

            if sudoTask.terminationStatus == 0 && isDaemonInstalled() {
                return (true, "已成功安装为系统服务，重启后将以最高优先级运行")
            }

            // 两种方案都失败
            let errData = sudoPipe.fileHandleForReading.readDataToEndOfFile()
            let errMsg = String(data: errData, encoding: .utf8) ?? ""
            if errMsg.contains("Sorry, try again") || errMsg.contains("incorrect password") {
                return (false, "密码错误")
            } else if errMsg.contains("Permission denied") || errMsg.contains("Operation not permitted") {
                return (false, "权限不足，请检查密码是否正确")
            } else {
                return (false, "安装失败: \(errMsg.isEmpty ? "未知错误" : errMsg)")
            }
        } catch {
            return (false, "执行失败: \(error.localizedDescription)")
        }
    }

    /// 卸载 LaunchDaemon（恢复为普通 App 模式）
    static func uninstall(password: String) -> (success: Bool, message: String) {
        let scriptContent = """
        #!/bin/bash
        launchctl unload \(daemonPlistPath) 2>/dev/null || true
        rm -f \(daemonPlistPath)
        rm -f \(daemonExecutablePath)
        echo "DAEMON_UNINSTALL_DONE"
        """

        let scriptPath = "/tmp/aurora_daemon_uninstall.sh"
        do {
            try scriptContent.write(toFile: scriptPath, atomically: true, encoding: .utf8)
            try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: scriptPath)
        } catch {
            return (false, "写脚本失败: \(error.localizedDescription)")
        }

        let escapedPwd = password.replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
        let appleScript = "do shell script \"bash \(scriptPath)\" password \"\(escapedPwd)\" with administrator privileges"

        let task = Process()
        task.launchPath = "/usr/bin/osascript"
        task.arguments = ["-e", appleScript]

        do {
            try task.run()
            task.waitUntilExit()

            if task.terminationStatus == 0 {
                return (true, "已卸载系统服务")
            } else {
                return (false, "卸载失败")
            }
        } catch {
            return (false, "执行失败: \(error.localizedDescription)")
        }
    }

    /// 获取当前可执行文件路径
    static func currentExecutablePath() -> String {
        return CommandLine.arguments[0]
    }
}

