    }

    deinit {
        // 释放 IOPMAssertion（进程退出时自动调用）
        if powerAssertionID != kIOPMNullAssertionID {
            IOPMAssertionRelease(powerAssertionID)
            print("[App] IOPMAssertion 已释放")
