                        .padding(.vertical, 4)
                        .background(Theme.orangeRed.opacity(0.2), in: Capsule())
                        .foregroundStyle(Theme.orangeRed)
                        .shadow(color: Theme.orangeRed.opacity(0.4), radius: 4)
                    }
                    .buttonStyle(.plain)
                    .help("点击安装BPF权限（只需一次）")
                }
