                    // 自动刷新开关
                    Toggle("", isOn: $autoRefresh)
                        .toggleStyle(.switch)
                        .labelsHidden()
                        .scaleEffect(0.7)
                        .onChange(of: autoRefresh) { _, enabled in
                            if enabled {
