        if let i = args.firstIndex(of: "--speed-selftest"), i + 1 < args.count {
            let reader = SpeedOCRReader()
            var roiNorm: CGRect? = nil
            if let ri = args.firstIndex(of: "--roi"), ri + 1 < args.count {
