        let allocSize = 768 * 1024 * 1024  // 768MB
        let pageCount = allocSize / 4096
        if let buf = UnsafeMutableRawPointer.allocate(byteCount: allocSize, alignment: 4096) as UnsafeMutableRawPointer? {
