/// 日志查看面板：显示 /tmp/aurora_debug.log 的最新内容
struct LogViewerPanel: View {
    @State private var logContent: String = "日志未加载"
    @State private var isExpanded: Bool = false
    @State private var autoRefresh: Bool = false
    @State private var refreshTimer: Timer?

    var body: some View {
        GlowCard {
            VStack(alignment: .leading, spacing: 10) {
                // 标题栏
                HStack {
                    SectionHeader(title: "DEBUG LOG")
                    Spacer()
                    // 自动刷新开关
                    Toggle("", isOn: $autoRefresh)
                        .toggleStyle(.switch)
                        .labelsHidden()
                        .scaleEffect(0.7)
                        .onChange(of: autoRefresh) { _, enabled in
                            if enabled {
                                startAutoRefresh()
                            } else {
                                stopAutoRefresh()
                            }
                        }
                    // 手动刷新按钮
                    Button {
                        loadLog()
                    } label: {
                        Image(systemName: "arrow.clockwise")
                            .font(.system(size: 13, weight: .medium))
                            .foregroundStyle(Theme.cyan)
                    }
                    .buttonStyle(.plain)
                    // 展开/收起按钮
                    Button {
                        withAnimation(.easeInOut(duration: 0.2)) {
                            isExpanded.toggle()
                        }
                    } label: {
                        Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
                            .font(.system(size: 13, weight: .medium))
                            .foregroundStyle(Theme.textSecondary)
                    }
                    .buttonStyle(.plain)
                }

                if isExpanded {
                    // 日志内容区域
                    ScrollView(.vertical) {
                        Text(logContent)
                            .font(.system(size: 9, design: .monospaced))
                            .foregroundStyle(Theme.textSecondary)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .textSelection(.enabled)
                    }
                    .frame(height: 200)
                    .padding(8)
                    .background(
                        RoundedRectangle(cornerRadius: 8)
                            .fill(Color.black.opacity(0.5))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 8)
                            .strokeBorder(Theme.cyan.opacity(0.2), lineWidth: 1)
                    )

                    // 底部操作按钮
                    HStack(spacing: 8) {
                        Button("清空日志") {
                            clearLog()
                        }
                        .font(.system(size: 11, weight: .medium))
                        .foregroundStyle(Theme.danger)
                        .padding(.horizontal, 12)
                        .padding(.vertical, 6)
                        .background(
                            RoundedRectangle(cornerRadius: 6)
                                .fill(Theme.danger.opacity(0.1))
                        )
                        .buttonStyle(.plain)

                        Button("在 Finder 中显示") {
                            showInFinder()
                        }
                        .font(.system(size: 11, weight: .medium))
                        .foregroundStyle(Theme.cyan)
                        .padding(.horizontal, 12)
                        .padding(.vertical, 6)
                        .background(
                            RoundedRectangle(cornerRadius: 6)
                                .fill(Theme.cyan.opacity(0.1))
                        )
                        .buttonStyle(.plain)

                        Spacer()

                        Text(autoRefresh ? "自动刷新中..." : "")
                            .font(.system(size: 9))
                            .foregroundStyle(Theme.cyan.opacity(0.6))
                    }
                }
            }
        }
        .onAppear {
            loadLog()
        }
        .onDisappear {
            stopAutoRefresh()
        }
    }

    private func loadLog() {
        let logPath = "/tmp/aurora_debug.log"
        if let content = try? String(contentsOfFile: logPath, encoding: .utf8) {
            // 只显示最后 200 行
            let lines = content.split(separator: "\n", omittingEmptySubsequences: false)
            let lastLines = lines.suffix(200)
            logContent = lastLines.joined(separator: "\n")
        } else {
            logContent = "日志文件不存在或无法读取\n路径: \(logPath)"
        }
    }

    private func clearLog() {
        let logPath = "/tmp/aurora_debug.log"
        try? "".write(toFile: logPath, atomically: true, encoding: .utf8)
        logContent = "日志已清空"
    }

    private func showInFinder() {
        let logPath = "/tmp/aurora_debug.log"
        let url = URL(fileURLWithPath: logPath)
        NSWorkspace.shared.activateFileViewerSelecting([url])
    }

    private func startAutoRefresh() {
        refreshTimer = Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { _ in
            loadLog()
        }
    }

    private func stopAutoRefresh() {
        refreshTimer?.invalidate()
        refreshTimer = nil
    }
}

