                        state.showDaemonInstallSheet = true
                    } label: {
                        HStack(spacing: 4) {
                            Image(systemName: "shield")
                                .font(.system(size: 9))
                            Text("升级")
                                .font(.system(size: 10, weight: .semibold, design: .rounded))
